<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Receipt {{ $order->number }} · {{ $business->name }}</title><link rel="stylesheet" href="{{ asset('css/app.css') }}"><script src="{{ asset('js/app.js') }}" defer></script></head><body class="receipt-body"><div class="receipt-actions"><a class="btn" href="{{ route('orders.show',$order) }}">Back to order</a><button class="btn primary" type="button" data-print><x-icon name="print"/>Print / save PDF</button></div><main class="receipt"><header class="receipt-header"><img src="{{ route('business.logo') }}" alt="Business logo"><h1>{{ $business->name }}</h1><p>{{ $business->address }}</p><p>{{ $business->phone }} {{ $business->email }}</p></header><div class="receipt-meta"><div><strong>ORDER RECEIPT</strong><br>{{ $order->number }}<br>Issued {{ $order->created_at->format('M j, Y · g:i A') }}</div><div><strong>{{ $order->customer->name }}</strong><br>{{ $order->customer->phone }}<br>Pickup: {{ $order->due_at->format('M j, Y · g:i A') }}</div></div><div class="table-wrap"><table><thead><tr><th>Service</th><th>Qty</th><th>Rate</th><th>Amount</th></tr></thead><tbody>@foreach($order->items as $item)<tr><td>{{ $item->name }}</td><td>{{ $item->quantity }} {{ $item->unit }}</td><td>{{ $business->money($item->unit_price_cents) }}</td><td>{{ $business->money($item->total_cents) }}</td></tr>@endforeach</tbody></table></div><div class="totals"><div><span>Subtotal</span><span>{{ $business->money($order->subtotal_cents) }}</span></div><div><span>Discount</span><span>− {{ $business->money($order->discount_cents) }}</span></div><div><span>Tax ({{ $order->tax_basis_points/100 }}%)</span><span>{{ $business->money($order->tax_cents) }}</span></div><div class="total-line"><span>Total</span><span>{{ $business->money($order->total_cents) }}</span></div><div><span>Net paid (after refunds)</span><span>{{ $business->money($order->paid_cents) }}</span></div><div class="total-line"><span>Balance due</span><span>{{ $business->money($order->balance_cents) }}</span></div></div>@if($order->payments->isNotEmpty())<h3>Payments received</h3><div class="table-wrap"><table><thead><tr><th>Date / staff</th><th>Method / reference</th><th>Amount</th></tr></thead><tbody>@foreach($order->payments as $p)<tr><td>{{ $p->created_at->format('M j · g:i A') }}<div class="table-sub">{{ $p->receiver->name }}</div></td><td>{{ ucwords(str_replace('_',' ',$p->method)) }}<div class="table-sub">{{ $p->reference }}</div></td><td>{{ $business->money($p->amount_cents) }}</td></tr>@endforeach</tbody></table></div>@endif<p class="receipt-note">Status: {{ \App\Models\Order::STATUSES[$order->status] }} · Rack: {{ $order->rack ?: '—' }} · Priority: {{ ucfirst($order->priority) }}</p>@include('partials.refund-history')<footer class="receipt-footer">{{ $business->receipt_footer }}<p class="receipt-note">Please present your order number when collecting your laundry.</p></footer></main></body></html>
